import matplotlib.pyplot as pltTRAMAS = ["", "//", "..", "xx", "\\\\", "oo", "++", "--"]MARCAS = ["o", "s", "^", "D", "v", "P", "X", "*"]def orden(df, fuente, dmo):    otras = [f for f in df[fuente].value_counts().index if f != dmo]    return [dmo] + otrasdef nombre(f):    return {"tripadvisor": "TripAdvisor", "sectur": "SECTUR"}.get(f, f.capitalize())def colores(fuentes, paleta):    cm = plt.get_cmap(paleta)    n = len(fuentes)    return {f: cm(0.15 + 0.7 * i / max(n - 1, 1)) for i, f in enumerate(fuentes)}def tramas(fuentes):    return {f: TRAMAS[i % len(TRAMAS)] for i, f in enumerate(fuentes)}def guardar(fig, ruta):    fig.savefig(ruta, dpi=150, bbox_inches="tight")    plt.close(fig)